-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Introdução à Tecnologia da Informação e Comunicação' and a.numero = 7
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 7 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Individual — Discursivas', 'PENDENTE', v_aula, 'Atividade — Atividade Individual — Discursivas (20 questões discursivas)',
      '/MATERIAIS/ASSISTENTE-DE-OPERACOES-LOGISTICAS/INTRODUCAO-TIC/ATIVIDADES/ATIVIDADE-SEXTA-FEIRA/ATIVIDADE-INDIVIDUAL-COMUNICACAO-TECNICA-DISCURSIVA.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Identificação dos cinco elementos na situação.', 1.0, 'Emissor: o supervisor do CD. Receptor: o operador da separação. Mensagem: o pedido 1520 é de sabão em pó, não de detergente. Canal: o rádio. Feedback: a resposta "Entendido, vou trocar".', 'Nota cheia: os cinco elementos corretos. Metade: três ou quatro corretos. Zero: dois ou menos.'),
      (v_atividade, 2, 1, 'Conceito de ruído, relação com a situação e atitude preventiva.', 1.0, 'Ruído é tudo o que atrapalha a mensagem a chegar como o emissor quis (barulho, falta de atenção, palavra ambígua). Na situação, a divisão das tarefas não foi entendida igual por todos. Atitudes: registrar os papéis na ata, repetir/confirmar quem faz cada texto, pedir feedback no fim da reunião.', 'Nota cheia: conceito, relação com o caso e uma atitude coerente. Metade: dois desses três. Zero: um ou nenhum.'),
      (v_atividade, 3, 1, 'Comentário assertivo e explicação.', 1.0, 'Ex.: "Sugiro trocar ''muitos pedidos'' por ''38 dos 150 pedidos'' e ''umas máquinas'' por ''2 dos 6 coletores de dados'', para o gerente entender o tamanho do problema." É assertivo porque é claro, específico, respeitoso e propõe uma solução, sem ofender nem deixar de apontar o erro.', 'Nota cheia: comentário específico, cordial, com sugestão e explicação correta. Metade: comentário adequado sem explicação, ou explicação sem comentário adequado. Zero: comentário agressivo/vago ou em branco.'),
      (v_atividade, 4, 1, 'Regras do brainstorming e justificativa dos papéis.', 1.0, 'Regras: todos falam na sua vez; nenhuma ideia é criticada na rodada; o líder registra e a decisão é por consenso. Todo aluno tem papel para que o trabalho seja dividido, ninguém fique sem tarefa e a nota individual possa ser conferida pelo que cada um escreveu.', 'Nota cheia: duas regras corretas e justificativa coerente. Metade: uma regra e justificativa, ou duas regras sem justificativa. Zero: regras erradas ou em branco.'),
      (v_atividade, 5, 1, 'Ata em parágrafo único, com abertura, decisões e encerramento.', 1.0, 'Ex.: "Aos nove dias do mês de outubro de dois mil e vinte e seis, às treze horas e trinta minutos, na sala 12, reuniram-se Ana, Bruno, Carla e Davi para dividir as tarefas do Manual de Comunicação do CD. Ficou decidido que Ana será a líder e escreverá a ata; Bruno será o pesquisador e escreverá o relatório; Carla será a redatora e escreverá o memorando; Davi será o formatador e escreverá o e-mail. Nada mais havendo, encerrou-se a reunião, e eu, Ana, escrevi esta ata."', 'Nota cheia: texto corrido, abertura (data, hora, local, participantes), decisões, encerramento e verbos no passado. Metade: falta uma dessas partes ou usa tópicos. Zero: não tem forma de ata.'),
      (v_atividade, 6, 1, 'Quatro linhas corretas com horário, setor e problema.', 1.0, '7h30 — Recebimento — 600 caixas guardadas no endereço errado; 8h às 11h — Separação — 38 de 150 pedidos errados; 11h — Armazenagem — 70 caixas de diferença; 13h — Armazenagem — 15 caixas vencidas; 15h — Expedição — 3 horas de atraso; 16h — e-mail falso (phishing).', 'Nota cheia: quatro ou mais linhas com horário, setor e problema corretos. Metade: duas ou três linhas corretas. Zero: uma ou nenhuma.'),
      (v_atividade, 7, 1, 'Parágrafo com as quatro causas, impessoal.', 1.0, 'As causas foram: o endereço B-03-04 foi trocado por B-04-03 no recebimento; 2 dos 6 coletores de dados pararam de ler o código de barras por problema de driver após a atualização; os pedidos foram anotados à mão, sem leitura do código; a regra FEFO não foi seguida na armazenagem do amaciante. Texto impessoal, sem citar nomes nem culpados.', 'Nota cheia: quatro causas corretas, terceira pessoa, sem culpar pessoas. Metade: duas ou três causas, ou culpa pessoas. Zero: uma causa ou nenhuma.'),
      (v_atividade, 8, 1, 'Cálculo correto e frase técnica.', 1.0, 'Diferença: 320 − 250 = 70 caixas. Ex.: "No inventário das 11h, foram encontradas 250 das 320 caixas previstas no endereço B-03-04, uma diferença de 70 caixas, provavelmente causada pela troca de endereço no recebimento e pelos pedidos anotados à mão."', 'Nota cheia: 70 caixas e frase técnica com número e causa. Metade: só o cálculo ou frase sem número correto. Zero: cálculo errado e sem frase.'),
      (v_atividade, 9, 1, 'Conceito de FEFO e aplicação ao caso.', 1.0, 'FEFO (First Expired, First Out) significa que sai primeiro o produto que vence primeiro. As caixas com validade mais próxima deveriam ficar na frente e ser expedidas antes; assim as antigas não ficariam esquecidas e não venceriam.', 'Nota cheia: conceito correto e aplicação ao caso. Metade: só um dos dois. Zero: conceito errado (ex.: confundir com o último que entra).'),
      (v_atividade, 10, 1, 'Duas sugestões, cada uma ligada a uma causa.', 1.0, 'Ex.: (1) conferir o endereço no coletor antes de guardar a carga — causa: endereço trocado; (2) consertar ou atualizar o driver dos coletores e ter coletores reserva — causa: coletores parados; (3) proibir pedidos anotados à mão — causa: separação sem código de barras; (4) organizar a prateleira pela validade (FEFO) — causa: produtos vencidos.', 'Nota cheia: duas sugestões viáveis, cada uma ligada a uma causa citada. Metade: uma sugestão ligada, ou duas sem ligação com a causa. Zero: nenhuma sugestão coerente.'),
      (v_atividade, 11, 1, 'Busca, avaliação da fonte e dados da referência.', 1.0, 'Busca: usar aspas para o termo exato, ex.: "o que é inventário rotativo" logística. Fonte confiável: site de instituição de ensino, órgão técnico ou empresa reconhecida, com autor e data, conferida em mais de uma fonte; evitar posts anônimos. Referência: nome do site, endereço (URL) e data de acesso. Texto com as próprias palavras.', 'Nota cheia: os três elementos corretos. Metade: dois. Zero: um ou nenhum, ou diz para copiar e colar.'),
      (v_atividade, 12, 1, 'Memorando com todas as partes e os dados do caso.', 1.0, 'Ex.: "MEMORANDO Nº 01/2026 — Para: Gerente do CD — De: Setor de TI — Data: 09/10/2026 — Assunto: Pedido de coletores de dados para a separação. Prezado(a) Gerente, solicitamos a compra de 2 coletores de dados, porque 2 dos 6 equipamentos estão parados desde a atualização do sistema (problema de driver), o que fez 38 dos 150 pedidos saírem errados e atrasou a expedição em 3 horas. Pedimos a compra até 16/10/2026. Atenciosamente, [nome] — Técnico de TI."', 'Nota cheia: cabeçalho completo, saudação, pedido com dados, prazo e fecho. Metade: falta uma ou duas partes. Zero: não tem forma de memorando.'),
      (v_atividade, 13, 1, 'Classificação dos três equipamentos com justificativa.', 1.0, 'Coletor de dados: entrada — leva a informação (código de barras) para o sistema. Impressora de etiquetas: saída — mostra/imprime a informação que vem do sistema. Cartão de memória: armazenamento — guarda os dados para uso posterior.', 'Nota cheia: três classificações corretas e justificadas. Metade: três corretas sem justificativa, ou duas corretas justificadas. Zero: uma ou nenhuma correta.'),
      (v_atividade, 14, 1, 'Conceito de driver, relação com o problema e conceito de WMS.', 1.0, 'Driver é o programa que faz o sistema operacional/sistema reconhecer e controlar um equipamento. Com a atualização, o driver dos coletores pode ter ficado incompatível ou desatualizado, então o equipamento liga mas o sistema não entende a leitura. WMS é o sistema de gerenciamento de armazém, que controla o estoque, os endereços e os pedidos do CD.', 'Nota cheia: os três pontos corretos. Metade: dois. Zero: um ou nenhum.'),
      (v_atividade, 15, 1, 'E-mail completo e adequado ao cliente.', 1.0, 'Ex.: "Para: compras@bompreco-ficticio.com.br — CC: comercial@rotacerta-ficticio.com.br — Assunto: Troca do pedido nº 1520 — sabão em pó. Prezados, pedimos desculpas pelo envio de detergente no lugar de sabão em pó. Houve uma falha na separação do pedido. O produto correto será entregue em 10/10/2026, e o produto enviado por engano será recolhido na mesma entrega. Atenciosamente, [nome] — Atendimento — Rota Certa Logística e Armazenagem."', 'Nota cheia: todos os campos, tom cordial, sem culpar colegas, solução com data, e-mails fictícios. Metade: faltam até dois campos ou a data. Zero: tom inadequado, culpa pessoas ou usa e-mail real.'),
      (v_atividade, 16, 1, 'Função do CC e justificativa sobre a frase.', 1.0, 'CC (com cópia) envia o e-mail também para quem precisa saber do assunto sem ser o destinatário principal; o comercial acompanha a reclamação e a solução do cliente. A frase não deve ser usada porque expõe e culpa um colega, mostra detalhes internos e passa má imagem da empresa; o certo é falar da falha no processo ("houve uma falha na separação").', 'Nota cheia: os dois pontos corretos. Metade: um. Zero: nenhum.'),
      (v_atividade, 17, 1, 'Conceito, dois sinais e conduta correta.', 1.0, 'Phishing é uma mensagem falsa que finge ser de alguém confiável para roubar dados (senhas). Sinais: pede a senha (o suporte nunca pede), urgência/pressa, remetente estranho, erros, links suspeitos. Conduta: não responder, não clicar, não passar a senha, avisar o TI/supervisor e apagar ou reportar o e-mail.', 'Nota cheia: conceito, dois sinais e conduta correta. Metade: dois desses três. Zero: um ou nenhum, ou diz que passaria a senha.'),
      (v_atividade, 18, 1, 'Quatro regras com verbo de ordem e frase de atenção.', 1.0, 'Ex.: 1. Crie uma senha forte, com letras, números e símbolos, e não a repita em outros sistemas. 2. Ative a verificação em duas etapas (código no celular). 3. Bloqueie a tela sempre que sair do computador (Windows + L). 4. Faça cópia de segurança (backup) dos arquivos importantes em outro lugar. ATENÇÃO: nunca passe sua senha para ninguém, nem para o suporte.', 'Nota cheia: quatro regras corretas, verbos de ordem, lista numerada e frase de atenção. Metade: três regras ou sem a frase de atenção. Zero: duas regras ou menos.'),
      (v_atividade, 19, 1, 'Três regras corretas e onde fazer.', 1.0, 'Margens: em cima e à esquerda 3 cm, embaixo e à direita 2 cm (Layout → Margens). Título 1: cada texto começa com o estilo Título 1 (Página Inicial → Estilos), o que permite o sumário automático (Referências → Sumário). Quebra de página antes de cada texto: Inserir → Quebra de página (Ctrl + Enter). Número de página: Inserir → Número de página. Fonte Arial/Calibri 12, espaço 1,5, justificado.', 'Nota cheia: três regras corretas com o local no editor. Metade: três regras sem o local, ou duas com o local. Zero: uma ou nenhuma correta.'),
      (v_atividade, 20, 1, 'Introdução completa, impessoal e com números.', 1.0, 'Ex.: "A Rota Certa Logística e Armazenagem mantém um centro de distribuição que atende 40 supermercados, organizado em recebimento, armazenagem, separação, conferência e expedição. Na segunda-feira, 38 dos 150 pedidos saíram errados, faltaram 70 caixas no inventário, 15 caixas venceram e a expedição atrasou 3 horas, com prejuízo de cerca de R$ 4.200. Este manual tem o objetivo de registrar o ocorrido e padronizar a comunicação do CD. Ele está organizado em cinco textos: ata, relatório, memorando, e-mail e regras de segurança."', 'Nota cheia: empresa, problema com números, objetivo e organização, na terceira pessoa. Metade: falta uma parte ou não usa números. Zero: falta mais de uma parte.');
end $$;
